; ============================================================================
; NETWARS - Borland C++ 1991 CRT0 / Startup Module
; Reverse-engineered from NETWARS.EXE (PKLITE 1.14 compressed)
;
; Assembled with: TASM /m /ml startup.asm
;
; This is the C run-time start-up code (crt0) generated by Borland C++ 3.1
; for the large memory model.  It:
;   1. Saves the data-segment selector in a CS-relative variable.
;   2. Calls DOS INT 21h/30h to get the DOS version.
;   3. Walks the PSP environment block to compute the argv[] string length.
;   4. Calls INT 21h/4Ah to trim the MCB to the program's actual needs.
;   5. Zeroes the BSS section.
;   6. Reads the real-time clock tick count for seeding srand().
;   7. Sets up the atexit / destructor chain via _FindBestFit.
;   8. Patches the divide-error ISR so it points at _DivErrHandler.
;   9. Calls _main (far call to code segment 0x60 offset 0x3B7).
;  10. Calls the atexit chain.
;  11. Calls far atexit[0..2] (C++ destructors for static objects).
;  12. Exits with INT 21h/4Ch using the return value from _main.
;
; Memory model: LARGE (all calls/returns are FAR; DS != CS)
; ============================================================================

DGROUP  GROUP  _DATA, _BSS

_TEXT   SEGMENT BYTE PUBLIC 'CODE'
        ASSUME CS:_TEXT, DS:DGROUP

; ----------------------------------------------------------------------------
; Exported variables (stored in CS-relative data at fixed offsets)
; These are written once during startup and never change afterward.
; ----------------------------------------------------------------------------
; CS:0x023C  _DataSeg       DW  0x2AE6   ; data segment (patched by reloc)
; DS:0x0090  _PspSeg        DW  ?        ; PSP segment   (from ES on entry)
; DS:0x0092  _DosVersion    DW  ?        ; AX from INT 21h/30h
; DS:0x008C  _EnvSeg        DW  ?        ; environment segment (from PSP:0x2C)
; DS:0x008E  _ArgvSize      DW  ?        ; paragraphs needed for argv
; DS:0x00A0  _HeapTop       DW  ?        ; segment of MCB top (= _PspSeg + paragraphs)
; DS:0x00A4  _HeapBase      DW  ?        ; initial heap pointer
; DS:0x00A8  _MemTop        DW  ?        ; top of usable memory
; DS:0x00A2  _HeapBaseHi    DW  ?        ; high word of heap base (32-bit ptr)
; DS:0x00A6  _HeapTopHi     DW  ?        ; high word of heap top  (32-bit ptr)
; DS:0x00A8  _SysMemTop     DW  ?
; DS:0x0096  _TimerTicksLow DW  ?        ; timer tick count (low word)
; DS:0x0098  _TimerTicksHi  DW  ?        ; timer tick count (high word)
; DS:0x0074  _OldInt0Off    DW  ?        ; original INT 0 handler offset
; DS:0x0076  _OldInt0Seg    DW  ?        ;   "         "   segment
; DS:0x0078  _OldInt4Off    DW  ?        ; original INT 4 handler offset
; DS:0x007A  _OldInt4Seg    DW  ?
; DS:0x007C  _OldInt5Off    DW  ?        ; original INT 5 (print-screen) handler
; DS:0x007E  _OldInt5Seg    DW  ?
; DS:0x0080  _OldInt6Off    DW  ?        ; original INT 6 handler
; DS:0x0082  _OldInt6Seg    DW  ?
; DS:0x0084  _ArgC          DW  ?        ; argc passed from DOS
; DS:0x0086  _ArgVOff       DW  ?        ; argv offset
; DS:0x0088  _ArgVSeg       DW  ?        ; argv segment
; DS:0x008A  _EnvSize       DW  ?        ; environment size in chars
; DS:0x37BA  _FarHeapBase   DW  ?
; DS:0x37C6  _FarHeapSize   DW  ?
; DS:0x364C  _HeapSegCount  DW  ?
; DS:0x3640  _AtExit0       DD  ?        ; atexit slot 0 (far ptr)
; DS:0x3644  _AtExit1       DD  ?        ; atexit slot 1
; DS:0x3648  _AtExit2       DD  ?        ; atexit slot 2
; DS:0x353C  _AtExitCount   DW  ?        ; number of registered atexit functions
; DS:0xC8xx  _AtExitTable   DD  20 dup ?; atexit function pointer table
; DS:0x39CC  _BssStart      DB  ?        ; start of BSS (zeroed by startup)

; ----------------------------------------------------------------------------
; _start  –  true entry point (CS:0x0000, reached via far jmp after PKLITE)
; ----------------------------------------------------------------------------
_start  PROC    FAR
        mov     dx, OFFSET DGROUP  ; 0x2AE6 (relocated by PKLITE)
        mov     [cs:023Ch], dx     ; save DS value while still in CS mode

        ; Get DOS version
        mov     ah, 30h
        int     21h
        mov     bp, [2]            ; PSP:0002 = first free segment above prog
        mov     bx, [2Ch]          ; PSP:002C = environment segment
        mov     ds, dx             ; switch to data segment
        mov     [92h], ax          ; save DOS version
        mov     [90h], es          ; save PSP segment
        mov     [8Ch], bx          ; save environment segment
        mov     [0A8h], bp         ; save free-memory top

        ; Initialise interrupt vectors (save old, install new)
        call    _SaveAndSetVectors

        ; Scan environment to determine argv string size
        les     di, [8Ah]          ; ES:DI -> environment block
        mov     ax, di
        mov     bx, ax
        mov     cx, 7FFFh          ; max search length
        cld
        repne   scasb              ; find first NUL
        jcxz    @@no_args          ; cx==0  means no args at all
        inc     bx
        @@scan_env:
        cmp     [es:di], al
        jnz     @@scan_env
        or      ch, 80h
        neg     cx
        mov     [8Ah], cx          ; env string length
        mov     cx, 1
        shl     bx, cl             ; *2 (word-align)
        add     bx, 8
        and     bx, -8             ; round up to 8-byte boundary
        mov     [8Eh], bx          ; argv paragraph count

        ; Compute how many paragraphs this process needs
        mov     dx, ds
        sub     bp, dx             ; bp = free paragraphs above DS
        mov     di, [37C6h]        ; _FarHeapSize
        cmp     di, 200h
        jnc     @@have_heap_size
        mov     di, 200h           ; minimum 0x200 paragraphs
        mov     [37C6h], di
        @@have_heap_size:
        add     di, 0C902h         ; add BSS + stack overhead
        jc      @@out_of_mem
        add     di, [37BAh]        ; add far-heap base
        jc      @@out_of_mem
        mov     cl, 4
        shr     di, cl             ; convert bytes to paragraphs
        inc     di
        cmp     bp, di
        jc      @@out_of_mem       ; not enough free memory

        ; Handle degenerate case (no far heap, little free memory)
        cmp     word [37C6h], 0
        jz      @@check_min
        cmp     word [37BAh], 0
        jnz     @@resize_mcb
        @@check_min:
        mov     di, 1000h          ; 64 KB minimum
        cmp     bp, di
        ja      @@resize_mcb
        mov     di, bp
        jmp     short @@resize_mcb
        @@out_of_mem:
        jmp     _MemError

        @@resize_mcb:
        mov     bx, di
        add     bx, dx             ; bx = new segment top
        mov     [0A0h], bx
        mov     [0A4h], bx         ; heap base = MCB top
        mov     ax, [90h]          ; PSP segment
        sub     bx, ax             ; paragraphs to keep
        mov     es, ax
        mov     ah, 4Ah            ; resize MCB
        push    di
        int     21h
        pop     di
        shl     di, cl             ; paragraphs -> bytes (cl=4 from above)

        ; Set up stack
        cli
        mov     ss, dx
        mov     sp, di
        sti

        ; Zero BSS section
        xor     ax, ax
        mov     es, [cs:023Ch]     ; ES = data segment
        mov     di, 039CCh         ; start of BSS
        mov     cx, 0C902h
        sub     cx, di             ; BSS size in bytes
        cld
        rep     stosb

        ; Read timer tick count (for srand seed)
        mov     ah, 0
        int     1Ah                ; INT 1A/00 – read system timer
        mov     [96h], dx          ; low word of tick count
        mov     [98h], cx          ; high word of tick count

        ; Find the best free-memory block for far heap
        xor     bp, bp
        mov     ax, OFFSET DGROUP   ; 0x2AE6
        mov     ds, ax
        mov     si, 039B4h
        mov     di, 039CCh
        call    _FindBestFit

        ; Restore DS and patch divide-error handler address
        mov     ds, [cs:023Ch]
        mov     byte [cs:01EDh], 72h  ; patch "jb" opcode
        mov     byte [cs:01DCh], 0    ; clear flag

        ; Push argc, argv for _main call
        push    word [88h]         ; argv segment
        push    word [86h]         ; argv offset
        push    word [84h]         ; argc

        ; Call far-heap initialiser in segment 0x8A0
        call    FAR PTR 08A0h:0004h

        ; Call _main (the actual game entry point)
        push    ax
        call    FAR PTR 0060h:03B7h

        ; Restore DS after _main returns
        mov     ax, OFFSET DGROUP
        mov     ds, ax

        ; Run atexit / destructor finalisation
        mov     si, 039CCh
        mov     di, 039CCh
        call    _FindBestFit

        ; Restore interrupt vectors
        mov     ds, [cs:023Ch]
        call    far [3640h]        ; atexit chain 0
        call    far [3644h]        ; atexit chain 1
        call    far [3648h]        ; atexit chain 2

        ; Verify BSS checksum and exit
        push    ax
        mov     ds, [cs:023Ch]
        push    cs
        call    _ExitWithCode

        ; Compute a simple checksum over the first 0x2F bytes of code
        xor     ax, ax
        mov     si, ax
        mov     cx, 2Fh
        @@chksum:
        add     al, [si]
        adc     ah, 0
        inc     si
        loop    @@chksum
        sub     ax, 0D5Ch
        jz      @@chksum_ok
        mov     cx, 19h
        mov     dx, 2Fh
        call    _PrintError
        @@chksum_ok:
        mov     bp, sp
        mov     ah, 4Ch            ; INT 21/4C = exit
        mov     al, [bp+4]         ; exit code from _main
        int     21h

        ; Alternate error exit
        mov     cx, 0Eh
        mov     dx, 48h
        jmp     _PrintErrorAndExit

@@no_args:
        jmp     @@resize_mcb

_start  ENDP


; ----------------------------------------------------------------------------
; _SaveAndSetVectors  –  save INT 0/4/5/6 and install divide-error handler
; ----------------------------------------------------------------------------
_SaveAndSetVectors  PROC  NEAR
        push    ds
        ; Save INT 0 (divide error)
        mov     ax, 3500h
        int     21h
        mov     [74h], bx
        mov     [76h], es
        ; Save INT 4 (overflow)
        mov     ax, 3504h
        int     21h
        mov     [78h], bx
        mov     [7Ah], es
        ; Save INT 5 (print screen)
        mov     ax, 3505h
        int     21h
        mov     [7Ch], bx
        mov     [7Eh], es
        ; Save INT 6 (invalid opcode)
        mov     ax, 3506h
        int     21h
        mov     [80h], bx
        mov     [82h], es
        ; Install our divide-error handler at INT 0
        mov     ax, 2500h
        mov     dx, cs
        mov     ds, dx
        mov     dx, OFFSET _DivErrHandler
        int     21h
        pop     ds
        ret
_SaveAndSetVectors  ENDP


; ----------------------------------------------------------------------------
; _RestoreVectors  –  restore original INT 0/4/5/6 on exit  (FAR)
; ----------------------------------------------------------------------------
_RestoreVectors  PROC  FAR
        push    ds
        mov     ax, 2500h
        lds     dx, [74h]
        int     21h
        pop     ds
        push    ds
        mov     ax, 2504h
        lds     dx, [78h]
        int     21h
        pop     ds
        push    ds
        mov     ax, 2505h
        lds     dx, [7Ch]
        int     21h
        pop     ds
        push    ds
        mov     ax, 2506h
        lds     dx, [80h]
        int     21h
        pop     ds
        retf
_RestoreVectors  ENDP


; ----------------------------------------------------------------------------
; _FindBestFit  –  scan the atexit list and invoke the highest-priority entry
;   SI = start of list, DI = end of list
; ----------------------------------------------------------------------------
_FindBestFit  PROC  NEAR
        mov     ah, 0FFh
        mov     dx, di
        mov     bx, si
        @@loop:
        cmp     bx, di
        jz      @@done
        cmp     byte [bx], 0FFh
        jz      @@next
        cmp     [bx+1], ah
        ja      @@next
        mov     ah, [bx+1]
        mov     dx, bx
        @@next:
        add     bx, 6
        jmp     short @@loop
        @@done:
        cmp     dx, di
        jz      @@ret
        mov     bx, dx
        push    ds
        pop     es
        push    es
        cmp     byte [bx], 0
        mov     byte [bx], 0FFh
        mov     ds, [cs:023Ch]
        jz      @@call
        call    far [es:bx+2]
        @@call:
        pop     ds
        ; (continues – rest of destructor chain walk omitted for brevity)
        @@ret:
        ret
_FindBestFit  ENDP


; ----------------------------------------------------------------------------
; _DivErrHandler  –  INT 0 (divide-by-zero / divide overflow) ISR
; ----------------------------------------------------------------------------
_DivErrHandler  PROC  FAR
        push    ax
        push    bx
        push    cx
        push    dx
        push    si
        push    di
        push    bp
        push    ds
        push    es
        push    cs
        pop     ds
        ; Print "Divide by zero!" message and terminate
        mov     dx, OFFSET _szDivideError
        mov     ah, 09h
        int     21h
        pop     es
        pop     ds
        pop     bp
        pop     di
        pop     si
        pop     dx
        pop     cx
        pop     bx
        pop     ax
        iret
_DivErrHandler  ENDP


; ----------------------------------------------------------------------------
; _MemError  –  print "Not enough memory" and exit
; ----------------------------------------------------------------------------
_MemError  PROC  NEAR
        mov     cx, 1Eh
        mov     dx, 56h
        ; fall through to _PrintError
_MemError  ENDP

_PrintError  PROC  NEAR
        ; cx = line count, dx = offset of message in CS
        push    cs
        pop     ds
        mov     ah, 09h
        int     21h
        mov     ax, 3
        push    ax
        push    cs
        call    _ExitWithCode
        ret
_PrintError  ENDP

_PrintErrorAndExit  PROC  NEAR
        push    cx
        mov     ds, [cs:023Ch]
        call    _PrintError
        pop     cx
        ret
_PrintErrorAndExit  ENDP

_ExitWithCode  PROC  NEAR
        ; ax = exit code
        mov     ah, 4Ch
        int     21h
_ExitWithCode  ENDP


; ----------------------------------------------------------------------------
; Read-only data (embedded in code segment at known offsets)
; ----------------------------------------------------------------------------
_szNotEnoughMem  DB  'Not enough memory$'
_szDivideError   DB  'Divide by zero!', 0Ah, 0

_TEXT   ENDS

        END  _start
